// Parametric stepped shaft
// Units: mm

$fn = 128;

shaft_d = 25;       // main (largest) shaft diameter

// [diameter, length]
steps = [
    [20, 18],
    [25, 35],
    [30, 45],
    [25, 35],
    [20, 18]
];

// Chamfer size
chamfer = 1.2;

// Optional keyway
show_keyway = true;
keyway_width = 6;
keyway_depth = 3;
keyway_start = 25;
keyway_length = 60;

module shaft_step(d, l) {
    cylinder(d=d, h=l);
}

function sum_lengths(n) =
    n == 0 ? 0 :
    steps[n-1][1] + sum_lengths(n-1);

module stepped_shaft() {
    difference() {
        union() {
            for (i = [0 : len(steps)-1]) {
                translate([0,0,sum_lengths(i)])
                    shaft_step(steps[i][0], steps[i][1]);
            }
        }

        // Keyway cut along top
        if (show_keyway)
            translate([-keyway_width/2, -steps[2][0]/2, keyway_start])
                cube([keyway_width, keyway_depth, keyway_length]);
    }
}

stepped_shaft();

// DIN 6885A keyed shaft — d=20 mm, L=100 mm
$fn = 128;

shaft_d   = 20;   // shaft diameter (mm)
shaft_len = 100;  // shaft length (mm)
keyway_w  = 6;    // keyway width (mm)
keyway_d  = 3;    // keyway depth (mm)

module keyed_shaft() {
    difference() {
        cylinder(h=shaft_len, d=shaft_d);
        translate([-keyway_w/2, shaft_d/2 - keyway_d, -1])
            cube([keyway_w, keyway_d + 1, shaft_len + 2]);
    }
}

keyed_shaft();

// Threaded shaft (lead screw) — M8x2, L=150 mm
$fn = 128;

shaft_d   = 8;     // nominal thread diameter (mm)
shaft_len = 150;   // shaft length (mm)
pitch     = 2.0;   // thread pitch (mm)

module threaded_shaft() {
    linear_extrude(height=shaft_len, twist=360*shaft_len/pitch)
        circle(d=shaft_d);
}

threaded_shaft();

// Clean external splined shaft
// Units: mm

$fn = 160;

// ---------- Parameters ----------
shaft_len = 160;
root_d = 28;          // valley diameter
outer_d = 34;         // tooth tip diameter
shaft_d = outer_d;    // alias: main shaft reference diameter
teeth = 28;

tooth_fill = 0.50;    // 0.45 to 0.60
end_chamfer = 1.2;

// ---------- 2D spline profile ----------
module spline_profile(root_d, outer_d, teeth, tooth_fill) {
    angle_step = 360 / teeth;
    r_root = root_d / 2;
    r_outer = outer_d / 2;

    polygon(points = [
        for (i = [0 : teeth - 1])
            let(
                a0 = i * angle_step - angle_step / 2,
                a1 = i * angle_step - angle_step * tooth_fill / 2,
                a2 = i * angle_step + angle_step * tooth_fill / 2,
                a3 = i * angle_step + angle_step / 2
            )
            each [
                [r_root  * cos(a0), r_root  * sin(a0)],
                [r_outer * cos(a1), r_outer * sin(a1)],
                [r_outer * cos(a2), r_outer * sin(a2)],
                [r_root  * cos(a3), r_root  * sin(a3)]
            ]
    ]);
}

// ---------- Shaft body ----------
module splined_shaft() {
    rotate([0, 90, 0])
        linear_extrude(height = shaft_len, center = true, convexity = 10)
            spline_profile(root_d, outer_d, teeth, tooth_fill);
}

// ---------- Optional simple end bevels ----------
module beveled_splined_shaft() {
    difference() {
        splined_shaft();

        // left bevel cut
        translate([-shaft_len/2 - 0.01, 0, 0])
            rotate([0, 90, 0])
                cylinder(
                    h = end_chamfer,
                    d1 = outer_d + 4,
                    d2 = root_d,
                    center = false
                );

        // right bevel cut
        translate([shaft_len/2 - end_chamfer + 0.01, 0, 0])
            rotate([0, 90, 0])
                cylinder(
                    h = end_chamfer,
                    d1 = root_d,
                    d2 = outer_d + 4,
                    center = false
                );
    }
}

beveled_splined_shaft();

// Transmission shaft with gears.scad helical gears
// Units: mm

use <D:/downloads/openscad_copilot (1)/openscad_copilot/gears.scad>

$fn = 96;

shaft_len = 347;
shaft_d = 18;
pressure_angle = 20;

module shaft_section(x, len, dia) {
    translate([x, 0, 0])
        rotate([0, 90, 0])
            cylinder(h = len, d = dia, center = false);
}

module library_helical_gear(x, width, teeth, module_size, helix_angle) {
    translate([x, 0, 0])
        rotate([0, 90, 0])
            spur_gear(
                modul = module_size,
                tooth_number = teeth,
                width = width,
                bore = 0,
                pressure_angle = pressure_angle,
                helix_angle = helix_angle,
                optimized = true
            );
}

module spline_section(x, width, root_d, outer_d, teeth = 24) {
    pitch = 360 / teeth;

    translate([x, 0, 0])
        rotate([0, 90, 0])
            linear_extrude(height = width, slices = 2)
                union() {
                    circle(d = root_d);
                    for (i = [0 : teeth - 1])
                        rotate(i * pitch)
                            polygon(points = [
                                [root_d / 2, -0.75],
                                [outer_d / 2, -0.45],
                                [outer_d / 2,  0.45],
                                [root_d / 2,  0.75]
                            ]);
                }
}

module transmission_shaft() {
    difference() {
        union() {
            // Stepped shaft core.
            shaft_section(0,   28, 18);
            shaft_section(28,  42, 34);
            shaft_section(70,  45, 28);
            shaft_section(115, 55, 26);
            shaft_section(170, 58, 24);
            shaft_section(228, 55, 22);
            shaft_section(283, 64, 18);

            // Library-generated helical gears.
            library_helical_gear(25,  30, 42, 1.9,  22);
            library_helical_gear(88,  24, 30, 1.8, -22);
            library_helical_gear(118, 24, 28, 1.8,  22);
            library_helical_gear(238, 24, 24, 1.8, -22);

            // Center dog spline.
            spline_section(174, 30, 30, 40, 24);

            // Shoulders.
            shaft_section(74,  8, 38);
            shaft_section(150, 8, 34);
            shaft_section(213, 8, 30);
            shaft_section(270, 7, 26);

            // End spline.
            spline_section(300, 25, 18, 25, 24);

            // Thread-ring representation.
            for (i = [0 : 8])
                shaft_section(330 + i * 2.1, 0.8, 22);
        }

        // Radial cross hole.
        translate([292, 0, 0])
            rotate([90, 0, 0])
                cylinder(h = 50, d = 5, center = true);
    }
}

transmission_shaft();

// Input shaft — three sections, L=120 mm
$fn = 128;

shaft_d   = 30;   // main (gear seat) diameter (mm)
bearing_d = 20;   // bearing / end section diameter (mm)

module input_shaft() {
    union() {
        cylinder(h=40, d=bearing_d);
        translate([0,0,40]) cylinder(h=40, d=shaft_d);
        translate([0,0,80]) cylinder(h=40, d=bearing_d);
    }
}

input_shaft();

// Parametric Line Shaft
// Units: mm

$fn = 120;

// -------------------------
// Shaft section
// -------------------------
module shaft_section(x, len, dia) {
    translate([x, 0, 0])
    rotate([0, 90, 0])
        cylinder(h = len, d = dia);
}

// -------------------------
// Bearing seat
// -------------------------
module bearing_seat(x, len, dia) {
    shaft_section(x, len, dia);
}

// -------------------------
// Keyway sleeve
// -------------------------
module keyed_section(x, len, dia, key_w = 8, key_d = 3) {
    difference() {
        shaft_section(x, len, dia);

        translate([x + len / 2, dia / 2 - key_d / 2, 0])
            cube([len + 2, key_d, key_w], center = true);
    }
}

// -------------------------
// Pulley
// -------------------------
module pulley(x, width, od, bore) {
    translate([x, 0, 0])
    rotate([0, 90, 0])
    difference() {
        union() {
            cylinder(h = width, d = od);

            translate([0, 0, width * 0.2])
                cylinder(h = width * 0.6, d = od * 0.75);
        }

        translate([0, 0, -1])
            cylinder(h = width + 2, d = bore);
    }
}

// -------------------------
// Complete Line Shaft
// -------------------------
module line_shaft() {
    union() {
        // Main shaft
        shaft_section(0, 500, 40);

        // Bearing seats
        bearing_seat(40, 40, 45);
        bearing_seat(420, 40, 45);

        // Keyed sections
        keyed_section(120, 80, 40);
        keyed_section(260, 80, 40);

        // Pulleys
        pulley(120, 40, 120, 40);
        pulley(260, 50, 180, 40);

        // Threaded end representation
        for (i = [0 : 12])
            shaft_section(470 + i * 2, 1, 44);
    }
}

line_shaft();

// Machine shaft — general purpose, L=150 mm
$fn = 128;

shaft_d   = 30;   // shaft diameter (mm)
shaft_len = 150;  // shaft length (mm)

module machine_shaft() {
    cylinder(h=shaft_len, d=shaft_d);
}

machine_shaft();

// Spindle shaft — two-section
$fn = 128;

shaft_d    = 20;   // spindle shaft diameter (mm)
flange_d   = 40;   // flange / toolholder diameter (mm)
shaft_len  = 100;  // shaft length (mm)
flange_len = 20;   // flange length (mm)

module spindle_shaft() {
    union() {
        cylinder(h=shaft_len, d=shaft_d);
        translate([0, 0, shaft_len])
            cylinder(h=flange_len, d=flange_d);
    }
}

spindle_shaft();

// D-flat shaft — flat ground on round section
$fn = 128;

shaft_d   = 6;    // shaft diameter (mm)
shaft_len = 50;   // shaft length (mm)
flat_depth = 1.0; // depth of flat cut from OD (mm)

module d_flat_shaft() {
    difference() {
        cylinder(h=shaft_len, d=shaft_d);
        translate([-shaft_d/2, shaft_d/2 - flat_depth, -1])
            cube([shaft_d, flat_depth + 1, shaft_len + 2]);
    }
}

d_flat_shaft();

// V6 crankshaft, 6-throw style
// One connected OpenSCAD body
// Units: mm

$fn = 180;

// Main dimensions
shaft_d = 18;  // main journal diameter (alias: shaft_d)
main_d = shaft_d;
rod_d  = 14;
throw  = 20;

// Layout
main_spacing = 34;
rod_len = 22;
web_t = 9;

// Web sizes
web_main_d = 44;
web_rod_d  = 32;

// Helper
module cyl_x(d,l){
    rotate([0,90,0])
        cylinder(d=d,h=l,center=true);
}

module web(x,ang){
    y = throw*cos(ang);
    z = throw*sin(ang);

    hull(){
        translate([x,0,0])
            cyl_x(web_main_d, web_t);

        translate([x,y,z])
            cyl_x(web_rod_d, web_t);
    }
}

module counterweight(x,ang){
    y = -throw*cos(ang);
    z = -throw*sin(ang);

    hull(){
        translate([x,y,z])
            scale([1,1.25,0.45])
                cyl_x(42, web_t);

        translate([x,y*0.45,z*0.45])
            scale([0.8,1,0.3])
                cyl_x(24, web_t);
    }
}

module rod_pin(x,ang){
    y = throw*cos(ang);
    z = throw*sin(ang);

    translate([x,y,z])
        cyl_x(rod_d, rod_len);
}

module crank_throw(x,ang){
    web(x-7,ang);
    web(x+7,ang);

    counterweight(x-7,ang);
    counterweight(x+7,ang);

    rod_pin(x,ang);

    // rod journal side collars
    y = throw*cos(ang);
    z = throw*sin(ang);

    translate([x-rod_len/2-2,y,z])
        cyl_x(20,4);

    translate([x+rod_len/2+2,y,z])
        cyl_x(20,4);
}

module v6_crankshaft() {
    union(){

        // Continuous center shaft
        cyl_x(main_d,260);

        // Main journals
        for(x=[-102,-68,-34,0,34,68,102])
            translate([x,0,0])
                cyl_x(22,16);

        // V6 crank throws, 120-degree phasing
        crank_throw(-85,   0);
        crank_throw(-51, 120);
        crank_throw(-17, 240);
        crank_throw( 17,   0);
        crank_throw( 51, 120);
        crank_throw( 85, 240);

        // Main bearing collars
        for(x=[-119,-68,0,68,119])
            translate([x,0,0])
                cyl_x(30,6);

        // Front stepped nose
        translate([-130,0,0])
            cyl_x(16,24);

        translate([-148,0,0])
            cyl_x(12,18);

        // Rear flywheel flange
        translate([130,0,0])
            cyl_x(34,12);

        translate([145,0,0])
            cyl_x(24,18);

        translate([162,0,0])
            cyl_x(50,10);
    }
}

v6_crankshaft();
